package com.tgrznar.javalearningapp.runner.sandbox.docker;

import com.tgrznar.javalearningapp.runner.sandbox.config.SandboxProperties;

import java.security.SecureRandom;
import java.util.ArrayList;
import java.util.HexFormat;
import java.util.List;
import java.util.regex.Pattern;

/**
 * Builds the argument list of {@code docker run} for one submission. It is a pure function, so the
 * isolation flags can be checked by a unit test without Docker.
 *
 * <p>Nothing user-controlled ends up in the arguments: the image comes from configuration, the
 * container name is generated by the runner and validated here, and the student's data travels only
 * through stdin as a tar archive. The flags mirror the spike (run-spike.ps1) that was verified on
 * Docker Desktop; keep the two in sync.
 *
 * <p>{@code --rm} is only a convenience: killing the {@code docker} client does not stop the
 * container, so the caller must always kill and remove it by name as well.
 */
public final class DockerRunCommand {

    /** Label that marks every sandbox container, used to find and remove orphans. */
    public static final String LABEL_KEY = "jla-sandbox";
    public static final String LABEL_VALUE = "1";

    /** Name format: jla-sbx-&lt;epochMillis&gt;-&lt;8 hex chars&gt;; the time part is used to age out orphans. */
    public static final Pattern CONTAINER_NAME = Pattern.compile("jla-sbx-(\\d{1,19})-[0-9a-f]{8}");

    private static final Pattern IMAGE = Pattern.compile("[a-z0-9][a-z0-9._/:@-]*");
    private static final SecureRandom RANDOM = new SecureRandom();

    private DockerRunCommand() {
    }

    /** Generates a fresh container name. */
    public static String newContainerName(long epochMillis) {
        byte[] bytes = new byte[4];
        RANDOM.nextBytes(bytes);
        return "jla-sbx-" + epochMillis + "-" + HexFormat.of().formatHex(bytes);
    }

    /** Returns the full command line, starting with the docker executable. */
    public static List<String> build(String containerName, SandboxProperties props) {
        if (!CONTAINER_NAME.matcher(containerName).matches()) {
            throw new IllegalArgumentException("Invalid container name");
        }
        if (!IMAGE.matcher(props.image()).matches()) {
            throw new IllegalArgumentException("Invalid image reference");
        }

        List<String> args = new ArrayList<>();
        args.add(props.dockerBinary());
        args.add("run");
        args.add("--rm");
        args.add("-i");
        args.addAll(List.of("--name", containerName));
        args.addAll(List.of("--label", LABEL_KEY + "=" + LABEL_VALUE));

        // The image must exist already; nothing is downloaded at run time.
        args.addAll(List.of("--pull", "never"));
        // No copy of the container output on the host disk (output is read from the attached stdout).
        args.addAll(List.of("--log-driver", "none"));

        args.addAll(List.of("--network", "none"));
        args.add("--read-only");
        args.addAll(List.of("--cap-drop", "ALL"));
        // Only what the launcher needs to hand the student's program to an unprivileged uid.
        args.addAll(List.of("--cap-add", "SETUID"));
        args.addAll(List.of("--cap-add", "SETGID"));
        args.addAll(List.of("--cap-add", "KILL"));
        args.addAll(List.of("--security-opt", "no-new-privileges"));
        args.addAll(List.of("--user", "0:0"));

        args.addAll(List.of("--memory", "512m"));
        args.addAll(List.of("--memory-swap", "512m"));
        args.addAll(List.of("--cpus", "1"));
        args.addAll(List.of("--pids-limit", "128"));
        args.addAll(List.of("--ulimit", "nofile=256:256"));

        args.addAll(List.of("--tmpfs", "/work:rw,nosuid,nodev,noexec,size=32m,mode=0711"));
        args.addAll(List.of("--tmpfs", "/build:rw,nosuid,nodev,noexec,size=16m,uid=10003,gid=10003,mode=0755"));
        args.addAll(List.of("--tmpfs", "/tmp:rw,nosuid,nodev,noexec,size=16m,mode=1777"));

        args.addAll(List.of("-e", "COMPILE_TIMEOUT_S=" + props.compileTimeoutSeconds()));
        args.addAll(List.of("-e", "RUN_TIMEOUT_S=" + props.runTimeoutSeconds()));
        args.addAll(List.of("-e", "MAX_OUTPUT_BYTES=" + props.maxOutputBytes()));
        args.addAll(List.of("-e", "MAX_CASES=" + props.maxCases()));

        args.add(props.image());
        return List.copyOf(args);
    }
}